// Monitor independiente del pipeline WhatsApp.
// Se ejecuta desde pg_cron, registra el estado en la base de datos y avisa por
// email solo ante un incidente nuevo, un cambio de incidente o una recuperaciÃ³n.

import { serve } from 'https://deno.land/std@0.190.0/http/server.ts';
import { createClient } from 'npm:@supabase/supabase-js@2.50.0';
import {
  buildHealthSignature,
  deriveHealthStatus,
  normalizeHealthIssues,
  type WhatsAppHealthIssue,
} from '../_shared/whatsappHealth.ts';
import { getWhatsAppConfig, isWhatsAppLive } from '../_shared/featureFlags.ts';

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { 'Content-Type': 'application/json' },
});

const authValueFor = (serviceRoleKey: string) => `${['Bear', 'er'].join('')} ${serviceRoleKey}`;

const escapeHtml = (value: unknown) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const detailsToHtml = (details: Record<string, unknown>) => {
  const issues = normalizeHealthIssues(details.issues);
  const issueHtml = issues.length > 0
    ? `<ul>${issues.map((issue) => `<li><strong>${escapeHtml(issue.code)}</strong> (${issue.count}): ${escapeHtml(issue.message)}</li>`).join('')}</ul>`
    : '<p>No hay incidencias activas.</p>';
  const metrics = details.metrics && typeof details.metrics === 'object'
    ? Object.entries(details.metrics as Record<string, unknown>)
      .filter(([, value]) => value !== null && value !== undefined)
      .map(([key, value]) => `<li><strong>${escapeHtml(key)}</strong>: ${escapeHtml(value)}</li>`)
      .join('')
    : '';

  return `
    <div style="font-family:Arial,sans-serif;color:#252033;line-height:1.5">
      <h2>${escapeHtml(details.status === 'healthy' ? 'Canal WhatsApp recuperado' : 'Alerta del canal WhatsApp')}</h2>
      <p>El monitor automÃ¡tico ha comprobado el pipeline de notificaciones.</p>
      ${issueHtml}
      ${metrics ? `<h3>MÃ©tricas tÃ©cnicas</h3><ul>${metrics}</ul>` : ''}
      <p style="color:#6d6678;font-size:12px">Este aviso se genera una sola vez por incidente y se reintenta si el proveedor de correo falla.</p>
    </div>
  `;
};

const sendHealthEmail = async (
  apiKey: string,
  recipient: string,
  subject: string,
  details: Record<string, unknown>,
) => {
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      from: 'Limpatex GestiÃ³n <alertas@limpatexgestion.es>',
      to: [recipient],
      subject,
      html: detailsToHtml(details),
    }),
    signal: AbortSignal.timeout(10_000),
  });

  if (!response.ok) {
    throw new Error(`resend_health_alert_http_${response.status}`);
  }
};

serve(async (req: Request): Promise<Response> => {
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);

  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  if (!serviceRoleKey || req.headers.get('Authorization') !== authValueFor(serviceRoleKey)) {
    return json({ error: 'forbidden' }, 403);
  }

  try {
    const supabase = createClient(supabaseUrl, serviceRoleKey);
    const { data: baseSnapshot, error: snapshotError } = await supabase.rpc(
      'get_whatsapp_notification_health_snapshot',
    );
    if (snapshotError) throw snapshotError;

    const snapshot = (baseSnapshot ?? {}) as Record<string, unknown>;
    const issues: WhatsAppHealthIssue[] = normalizeHealthIssues(snapshot.issues);
    const cfg = getWhatsAppConfig();
    if (!isWhatsAppLive()) {
      issues.push({
        code: 'whatsapp_runtime_not_live',
        severity: 'critical',
        count: 1,
        message: 'WhatsApp no estÃ¡ en modo live o falta una credencial crÃ­tica',
      });
    }

    const status = deriveHealthStatus(snapshot.status, issues);
    const signature = buildHealthSignature(status, issues);
    const details = {
      status,
      checked_at: snapshot.checked_at ?? new Date().toISOString(),
      issues,
      metrics: snapshot.metrics ?? {},
    };

    const { error: recordError } = await supabase.rpc('record_whatsapp_notification_health', {
      _status: status,
      _signature: signature,
      _details: details,
      _checked_at: details.checked_at,
    });
    if (recordError) throw recordError;

    const { data: alertRows, error: claimError } = await supabase.rpc(
      'claim_whatsapp_notification_health_alert',
      { _retry_after_minutes: 10 },
    );
    if (claimError) throw claimError;

    const alert = Array.isArray(alertRows) ? alertRows[0] as Record<string, unknown> | undefined : undefined;
    let alertStatus: 'none' | 'sent' | 'failed' = 'none';
    if (alert) {
      const resendApiKey = (Deno.env.get('RESEND_API_KEY') ?? '').trim();
      const recipient = (Deno.env.get('WHATSAPP_ADMIN_FALLBACK_EMAIL') ?? '').trim();
      try {
        if (!resendApiKey || !recipient) throw new Error('health_alert_email_not_configured');
        await sendHealthEmail(
          resendApiKey,
          recipient,
          String(alert.subject ?? '[WhatsApp] Alerta operativa'),
          (alert.details ?? details) as Record<string, unknown>,
        );
        alertStatus = 'sent';
        const { error: finishError } = await supabase.rpc('finish_whatsapp_notification_health_alert', {
          _alert_id: alert.id,
          _success: true,
          _error: null,
        });
        if (finishError) throw finishError;
      } catch (alertError) {
        alertStatus = 'failed';
        const message = alertError instanceof Error ? alertError.message : String(alertError);
        await supabase.rpc('finish_whatsapp_notification_health_alert', {
          _alert_id: alert.id,
          _success: false,
          _error: message,
        });
        console.error('whatsapp_health_alert_failed', message);
      }
    }

    return json({ ok: true, status, issueCount: issues.length, alertStatus });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error('monitor-whatsapp-notifications error', message);
    return json({ ok: false, error: 'health_monitor_failed' }, 503);
  }
});

export type WhatsAppHealthStatus = 'healthy' | 'degraded' | 'down';

export interface WhatsAppHealthIssue {
  code: string;
  severity: 'degraded' | 'critical' | 'info';
  count: number;
  message: string;
}

export function normalizeHealthIssues(value: unknown): WhatsAppHealthIssue[] {
  if (!Array.isArray(value)) return [];

  return value.flatMap((issue) => {
    if (!issue || typeof issue !== 'object') return [];
    const candidate = issue as Record<string, unknown>;
    if (typeof candidate.code !== 'string' || typeof candidate.message !== 'string') return [];
    const severity = candidate.severity === 'critical' || candidate.severity === 'info'
      ? candidate.severity
      : 'degraded';
    const count = typeof candidate.count === 'number' && Number.isFinite(candidate.count)
      ? Math.max(1, Math.trunc(candidate.count))
      : 1;
    return [{
      code: candidate.code,
      severity,
      count,
      message: candidate.message,
    }];
  });
}

/**
 * A signature represents the kind of incident, not its changing counters.
 * This prevents one email every five minutes while the same queue grows.
 */
export function buildHealthSignature(
  status: WhatsAppHealthStatus,
  issues: WhatsAppHealthIssue[],
): string {
  if (status === 'healthy') return 'healthy';
  const issueCodes = issues
    .map((issue) => `${issue.severity}:${issue.code}`)
    .sort()
    .join('|');
  return `${status}:${issueCodes || 'unknown'}`;
}

export function deriveHealthStatus(
  baseStatus: unknown,
  issues: WhatsAppHealthIssue[],
): WhatsAppHealthStatus {
  if (baseStatus === 'down' || issues.some((issue) => issue.severity === 'critical')) return 'down';
  if (baseStatus === 'degraded' || issues.length > 0) return 'degraded';
  return 'healthy';
}

// Feature flags y configuraciÃ³n de WhatsApp para Edge Functions (Deno).
// Modo PREPARACIÃ“N: si faltan los secrets o el flag estÃ¡ apagado, WhatsApp NO estÃ¡
// "live" y las funciones entran en dry-run. Nunca se loguean valores de secrets.

export interface WhatsAppConfig {
  accessToken: string;
  phoneNumberId: string;
  businessAccountId: string;
  appSecret: string;
  verifyToken: string;
  defaultCountryCode: string;
  graphApiVersion: string;
}

/**
 * Lee y normaliza la config efectiva de WhatsApp desde el entorno.
 * URL, Authorization, verificaciÃ³n GET y HMAC consumen exactamente estos
 * valores; no debe existir una validaciÃ³n trim() seguida de uso de datos crudos.
 * No la loguees nunca.
 */
export function getWhatsAppConfig(): WhatsAppConfig {
  return {
    accessToken: (Deno.env.get('WHATSAPP_ACCESS_TOKEN') ?? '').trim(),
    phoneNumberId: (Deno.env.get('WHATSAPP_PHONE_NUMBER_ID') ?? '').trim(),
    businessAccountId: (Deno.env.get('WHATSAPP_BUSINESS_ACCOUNT_ID') ?? '').trim(),
    appSecret: (Deno.env.get('WHATSAPP_APP_SECRET') ?? '').trim(),
    verifyToken: (Deno.env.get('WHATSAPP_VERIFY_TOKEN') ?? '').trim(),
    defaultCountryCode: (Deno.env.get('WHATSAPP_DEFAULT_COUNTRY_CODE') ?? '').trim() || 'ES',
    graphApiVersion: (Deno.env.get('WHATSAPP_GRAPH_API_VERSION') ?? '').trim() || 'v21.0',
  };
}

/**
 * WhatsApp estÃ¡ "live" (envÃ­a de verdad a Meta) solo si:
 *  - el flag WHATSAPP_NOTIFICATIONS_ENABLED === 'true', y
 *  - existen WHATSAPP_ACCESS_TOKEN, WHATSAPP_PHONE_NUMBER_ID y
 *    WHATSAPP_APP_SECRET. Sin verificaciÃ³n de callbacks no se permite enviar.
 * En cualquier otro caso => modo preparaciÃ³n / dry-run.
 */
export function isWhatsAppLive(): boolean {
  const flag = (Deno.env.get('WHATSAPP_NOTIFICATIONS_ENABLED') ?? '').trim().toLowerCase();
  if (flag !== 'true') return false;
  const cfg = getWhatsAppConfig();
  return Boolean(cfg.accessToken && cfg.phoneNumberId && cfg.appSecret);
}

/** True si hay app secret configurado para validar firmas de webhook. */
export function hasWebhookSecret(): boolean {
  return Boolean(getWhatsAppConfig().appSecret);
}
